<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { Head } from '@inertiajs/vue3';
import ErpLayout from '@/layouts/ErpLayout.vue';
import Icon from '@/components/dashboard/Icon.vue';
import { useAuthorization } from '@/composables/useAuthorization';
interface Props { userName?: string; userEmail?: string }
interface OrderItem { id: number; product_name: string; variant_name?: string; sku?: string; quantity: string; unit_price: string; returnable_quantity: number }
interface Order { id: number; order_number: string; customer_name: string; location_id: number; items: OrderItem[] }
interface CashAccount { id: number; code: string; name: string }
interface ReturnRecord { id: number; return_number: string; return_date: string; refund_amount: string; refund_method: string; status: string; order?: { order_number: string; customer_name: string }; journal_entry?: { entry_number: string; status: string } }
const props = withDefaults(defineProps<Props>(), { userName: '', userEmail: '' });
const { can } = useAuthorization();
const orders = ref<Order[]>([]); const cashAccounts = ref<CashAccount[]>([]); const records = ref<ReturnRecord[]>([]);
const loading = ref(false); const saving = ref(false); const error = ref(''); const success = ref('');
const form = reactive({ sales_order_id: '', return_date: new Date().toISOString().slice(0,10), refund_method: 'cash', cash_account_id: '', reason: '', quantities: {} as Record<number,string> });
const selectedOrder = computed(() => orders.value.find(o => String(o.id) === form.sales_order_id));
const total = computed(() => (selectedOrder.value?.items ?? []).reduce((sum, item) => sum + Number(form.quantities[item.id] || 0) * Number(item.unit_price), 0));
const csrf = () => decodeURIComponent(document.cookie.split('; ').find(v => v.startsWith('XSRF-TOKEN='))?.split('=').slice(1).join('=') ?? '');
async function api<T>(url: string, options: RequestInit = {}): Promise<T> { const r = await fetch(url,{credentials:'same-origin',...options,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest',...(options.body?{'Content-Type':'application/json','X-XSRF-TOKEN':csrf()}:{}),...(options.headers??{})}}); const p=await r.json().catch(()=>({})); if(!r.ok) throw new Error(p.message||Object.values(p.errors??{}).flat().join(' ')||`Request failed (${r.status})`); return p as T; }
async function load(): Promise<void> { loading.value=true; error.value=''; try { const [o,r]=await Promise.all([api<{data:Order[];cash_accounts:CashAccount[]}>('/api/sales-returns/options'),api<{data:ReturnRecord[]}>('/api/sales-returns?per_page=50')]); orders.value=o.data; cashAccounts.value=o.cash_accounts; records.value=r.data; if(!form.cash_account_id&&cashAccounts.value.length) form.cash_account_id=String(cashAccounts.value[0].id); } catch(e){error.value=e instanceof Error?e.message:'Unable to load sales returns.';} finally{loading.value=false;} }
async function submit(): Promise<void> { if(!selectedOrder.value) return; const items=selectedOrder.value.items.filter(i=>Number(form.quantities[i.id]||0)>0).map(i=>({sales_order_item_id:i.id,quantity:form.quantities[i.id]})); if(!items.length){error.value='Select at least one return quantity.';return;} saving.value=true;error.value='';try{await api('/api/sales-returns',{method:'POST',body:JSON.stringify({sales_order_id:Number(form.sales_order_id),idempotency_key:crypto.randomUUID(),return_date:form.return_date,refund_method:form.refund_method,cash_account_id:form.refund_method==='store_credit'?null:Number(form.cash_account_id),reason:form.reason,items})});success.value='Return completed. Inventory and finance ledgers have been updated.';form.sales_order_id='';form.quantities={};form.reason='';await load();}catch(e){error.value=e instanceof Error?e.message:'Unable to complete return.';}finally{saving.value=false;} }
onMounted(load);
</script>

<template>
<Head title="Sales Returns & Refunds" />
<ErpLayout :user-name="props.userName" :user-email="props.userEmail">
<section class="sr-page">
  <header class="sr-header">
    <div><nav class="sr-crumb" aria-label="Breadcrumb"><a href="/dashboard">Workspace</a><Icon name="chevron-right" :size="12"/><a href="/orders">Sales</a><Icon name="chevron-right" :size="12"/><strong>Sales Returns</strong></nav>
      <div class="sr-title"><span class="sr-title-icon"><Icon name="undo-2" :size="20"/></span><div><h1>Sales Returns &amp; Refunds</h1><p>Process fulfilled-item returns, restore inventory and record customer refunds.</p></div></div>
    </div>
    <button class="sr-btn sr-secondary" type="button" :disabled="loading" @click="load"><Icon name="refresh-cw" :size="14"/>{{ loading ? 'Refreshing…' : 'Refresh records' }}</button>
  </header>
  <div v-if="error" class="sr-alert sr-alert-error" role="alert"><Icon name="alert-circle" :size="17"/><span>{{ error }}</span><button type="button" aria-label="Dismiss error" @click="error=''"><Icon name="x" :size="14"/></button></div>
  <div v-if="success" class="sr-alert sr-alert-success" role="status"><Icon name="check-circle-2" :size="17"/><span>{{ success }}</span><button type="button" aria-label="Dismiss success" @click="success=''"><Icon name="x" :size="14"/></button></div>
  <section class="sr-kpis" aria-label="Sales return overview">
    <article><span class="sr-kpi-icon"><Icon name="receipt" :size="17"/></span><div><small>Recorded returns</small><strong>{{ records.length.toLocaleString('en-BD') }}</strong></div></article>
    <article><span class="sr-kpi-icon sr-kpi-green"><Icon name="wallet" :size="17"/></span><div><small>Total refunds</small><strong>BDT {{ records.reduce((sum,item)=>sum+Number(item.refund_amount||0),0).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2}) }}</strong></div></article>
    <article><span class="sr-kpi-icon sr-kpi-blue"><Icon name="package-check" :size="17"/></span><div><small>Eligible orders</small><strong>{{ orders.length.toLocaleString('en-BD') }}</strong></div></article>
  </section>
  <section v-if="can('system.sales_returns.create')" class="sr-card">
    <header class="sr-card-head"><div class="sr-section-icon"><Icon name="corner-up-left" :size="17"/></div><div class="sr-head-copy"><h2>Process a sales return</h2><p>Select a fulfilled order, specify return quantities and choose the refund method.</p></div><span class="sr-chip">Return workflow</span></header>
    <div class="sr-card-body">
      <div class="sr-form-grid">
        <label><span>Sales order <i>*</i></span><select v-model="form.sales_order_id" required><option value="">Choose fulfilled order</option><option v-for="o in orders" :key="o.id" :value="String(o.id)">{{ o.order_number }} — {{ o.customer_name }}</option></select><small>Only orders with fulfilled quantities are available.</small></label>
        <label><span>Return date</span><input v-model="form.return_date" type="date"></label>
        <label><span>Refund method</span><select v-model="form.refund_method"><option value="cash">Cash refund</option><option value="bank">Bank refund</option><option value="store_credit">Customer store credit</option></select></label>
        <label v-if="form.refund_method!=='store_credit'" class="sr-wide"><span>Refund cash / bank account</span><select v-model="form.cash_account_id"><option value="">Choose account</option><option v-for="a in cashAccounts" :key="a.id" :value="String(a.id)">{{ a.code }} — {{ a.name }}</option></select></label>
      </div>
      <div v-if="selectedOrder" class="sr-items">
        <div class="sr-subhead"><div><h3>Items eligible for return</h3><p>{{ selectedOrder.order_number }} · {{ selectedOrder.customer_name }}</p></div><span class="sr-chip">{{ selectedOrder.items.length }} items</span></div>
        <div class="sr-table-wrap"><table class="sr-table"><thead><tr><th scope="col">Product</th><th scope="col">Sold qty</th><th scope="col">Returnable</th><th scope="col">Return qty</th><th scope="col" class="sr-right">Unit price</th></tr></thead><tbody>
          <tr v-for="i in selectedOrder.items" :key="i.id"><td><strong>{{ i.product_name }} {{ i.variant_name||'' }}</strong><small>{{ i.sku||'SKU not set' }}</small></td><td>{{ i.quantity }}</td><td><span class="sr-qty">{{ i.returnable_quantity.toFixed(4) }}</span></td><td><input v-model="form.quantities[i.id]" class="sr-qty-input" type="number" min="0" :max="i.returnable_quantity" step="0.0001" :aria-label="`Return quantity for ${i.product_name}`" :disabled="i.returnable_quantity<=0"></td><td class="sr-right sr-money">BDT {{ Number(i.unit_price).toFixed(2) }}</td></tr>
        </tbody></table></div>
      </div>
      <div v-else class="sr-placeholder"><Icon name="package-search" :size="21"/><div><strong>Select an order to continue</strong><p>Its fulfilled items and remaining returnable quantities will appear here.</p></div></div>
      <label class="sr-reason"><span>Return reason <small>(optional)</small></span><input v-model="form.reason" maxlength="500" placeholder="Add a short reason for this return"></label>
    </div>
    <footer class="sr-footer"><div><small>Estimated refund total</small><strong>BDT {{ total.toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2}) }}</strong></div><button class="sr-btn sr-primary" type="button" :disabled="saving||!selectedOrder||total<=0" @click="submit"><Icon :name="saving?'loader-circle':'check-circle-2'" :size="15"/>{{ saving?'Processing return…':'Complete return & refund' }}</button></footer>
    <div class="sr-note"><Icon name="shield-check" :size="14"/>Returns restore eligible inventory and post the corresponding immutable refund journal entry.</div>
  </section>
  <section class="sr-card sr-records">
    <header class="sr-card-head"><div class="sr-section-icon sr-muted-icon"><Icon name="clipboard-list" :size="17"/></div><div class="sr-head-copy"><h2>Recent return records</h2><p>Completed return and refund transactions.</p></div><span class="sr-chip">{{ records.length }} records</span></header>
    <div v-if="loading" class="sr-state"><span class="sr-loader"></span><strong>Loading return records…</strong></div>
    <div v-else-if="!records.length" class="sr-state"><span class="sr-empty-icon"><Icon name="receipt-text" :size="22"/></span><strong>No sales returns recorded yet</strong><p>Completed returns will appear here with their refund and journal details.</p></div>
    <div v-else class="sr-table-wrap"><table class="sr-table sr-record-table"><thead><tr><th scope="col">Return reference</th><th scope="col">Sales order / customer</th><th scope="col">Return date</th><th scope="col">Refund method</th><th scope="col" class="sr-right">Refund amount</th><th scope="col">Journal entry</th><th scope="col">Status</th></tr></thead><tbody>
      <tr v-for="r in records" :key="r.id"><td><strong class="sr-ref">{{ r.return_number }}</strong><small>Return #{{ r.id }}</small></td><td><strong>{{ r.order?.order_number||'—' }}</strong><small>{{ r.order?.customer_name||'Customer unavailable' }}</small></td><td class="sr-nowrap">{{ r.return_date }}</td><td class="sr-capitalize">{{ r.refund_method.replace('_',' ') }}</td><td class="sr-right sr-money">BDT {{ Number(r.refund_amount).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2}) }}</td><td><strong>{{ r.journal_entry?.entry_number||'—' }}</strong><small>{{ r.journal_entry?.status||'Not available' }}</small></td><td><span class="sr-status" :class="`status-${(r.status||'unknown').toLowerCase().replace(/[^a-z0-9_-]/g,'-')}`">{{ r.status }}</span></td></tr>
    </tbody></table></div>
  </section>
</section>
</ErpLayout>
</template>
<style scoped>
